// --- THE LOGIC (What we want to test) ---
// const emailService = require('./emailService');

// We want to test this logic without ACTUALLY sending emails to real people.
function registerUser(name, emailServiceMock) {
  console.log(`Registering ${name} in DB...`);

  // This triggers an email
  emailServiceMock.sendWelcomeEmail(name);
  return true;
}

// --- THE MOCK (Fake dependency) ---
const mockEmailService = {
  // A spy function that just remembers it was called
  sendWelcomeEmail: function(name) {
    this.calledWith = name;
    this.callCount++;
  },
  callCount: 0,
  calledWith: null
};

// --- THE TEST ---
registerUser("Alice", mockEmailService);

// We ASSERT that the logic properly attempted to send the email
console.log("Was email service called?", mockEmailService.callCount === 1);
console.log("Was it called with the correct name?", mockEmailService.calledWith === "Alice");
// We verified the code works perfectly, and nobody actually received an email!
